// Four Stone Kings Over the River: a great desert river at the first sun. The flight threads a channel among
// boulders of black river-worn granite, wet and shining in white water (one in five dark red), runs low and close
// along a shore of honey sand (reeds and papyrus in the
// shallows, palms leaning over the water, a half-buried temple with its two rows of stone lions, a small white
// steamer tied in a bay of the bank, then a short cove with one palmed point), bends out onto the river before
// four seated stone kings cut in the highest bluff of a long line of desert cliffs (the hero,
// src/parts/four-stone-kings-over-the-river.js), flies a row along them sixty metres out, where the two middle
// kings are seen whole, turns once more onto the door's axis (the turn ends over the bank, thirty metres out),
// and goes straight in, low over sand and ledge, between the middle pair into the lit door, where the portal
// stands. No built thing meets the water before the kings: the terrace meets the river as the land does.
//
// Metres; the water is y = 0 (the seed sets the river's level a little above it); we travel up-river, at first
// toward -Z, with the west bank on +X. THE CLIFF FRAME: F is the middle of the door's threshold, TN points out of
// the face over the river, TT runs along the face to the right as seen from the water; a place is (s, d).
// THE STATIONS OF THE PLACE, each laid from the one before it: the cataract's last boulders (B_Z1); the temple's
// avenue AVENUE metres beyond them; the steamer's berth, its stern BERTH.gap metres beyond the avenue's up-river row;
// the kings, the first king's outer foot KINGS_ALONG metres (FRONTS lengths of the cut front) beyond the steamer's bow.
// Nothing here goes with the visitor and nothing begins, turns or ends as the visitor comes: boats, birds and
// camels keep loops and habits of their own on the world's clock; the steamer is in one idle state
// for the whole visit; the hour is one standing hour from the first metre to the last.
// The eye is drawn by camera.nearThrough: the entry stands in a pool of the cataract, ENTRY_IN metres inside the
// boulders' first line. (The pool, the clear axis behind the entry and how the channel is aimed, so that the
// door is seen up it: the list's first two entries.)
// THINGS PLACED BY HOW THEY ARE SEEN FROM THE WAY (to be seen, or to stay out of a view). The owner's rule: each
// is typed, is said here, and holds for its whole stretch and on every seed. What is placed may be dealt by a
// stream or move on the world's clock; the margin, the place in metres or the bearing named in each entry is
// typed and reads neither, nor the lens, nor a share of the flight: it is a number, the range a draw is made
// in, or a rule that finds the place in the world's frame or on the line's own metres (the line itself is
// laid from typed measures and one draw: how far river-side of the shore line its pool lies).
//  - THE ENTRY'S POOL AND THE CLEAR AXIS BEHIND IT: no boulder's skin stands within POOL = 26 m of the entry, and
//    the lane that keeps the boulders off the route's line (BREADTHS, below) is carried back from the entry
//    along the channel's heading for ENTRY_IN + 24 = 68 m (a point every 2 m, the last 66 m back; the boulders'
//    first line lies ENTRY_IN = 44 m down-river of the entry): so that the axis the eye is drawn in along is
//    clear of boulders back to open river, and the flight begins in open water.
//  - THE CHANNEL IS AIMED AT THE DOOR: from the entry the line runs STRAIGHT = 60 m straight at the middle of the
//    door's threshold, level, 2.2 m over the water: so that the front is seen up the channel from the first
//    metre; every seed's channel (a stream gives only how far river-side of the shore line its pool lies).
//  - THE DOOR'S SIGHT AND THE GATE'S: no boulder over 4.5 m high stands in the straight sights from the channel
//    (from a place every 10 m of the line through the cataract, wherever the boulder would lie more than 30 m on
//    from that place and short of the door or the gate) to the kings' door or to the buried temple's gate, in a
//    corridor of the boulder's own half breadth and 3 m (inSight): one law, both sights, every boulder of the
//    field.
//  - A BOULDER IS PASSED AT ONE AND A HALF OF ITS OWN BREADTHS (BREADTHS = 1.5, skin to line, and never nearer
//    than SKIN = 6 m): so that it is seen whole as a boulder; every boulder of every kind, the whole cataract.
//  - THE CHANNEL'S WALLS: on either hand of the line, from the pool's far side (the first station 4 to 12 m
//    beyond it) to the last boulders' line, a boulder's station every 15 to 24 m of the line, its skin 6.3 to
//    12 m from it or as far as the rule above keeps one of its size (to 19.4 m), 3.5 to 8.5 m high (4.4 where a
//    taller one would stand in a sight; a station's boulder is left out where another rule of the field
//    forbids it there): so that the channel is a channel; stations, gaps, sizes and colour are the stream
//    'boulders'.
//  - THE BIRDS ON THE BOULDERS (the egrets, the cormorants, the cormorants that dry their wings) stand only on
//    boulders 2.5 m and more high whose skin lies within 30 m of the channel's line: beside the way; the whole
//    cataract (which of those boulders bears a bird is a stream's shuffle).
//  - THE LOW CORMORANTS' OVAL lies beside the channel on the river's side, laid from the route's own point at
//    the middle metre of the boulders' stretch (midway between POOL metres of the line and the lane's end, 30 m
//    past the last boulders' line): its near side CORM.off = 37 m from that point, its long axis (90 m) along
//    the channel's heading there, 1.5 m over the water: one pair low over the cataract's water, beside the way.
//    (The pair flies it on the world's clock, and only where the oval has its room; the oval's place reads no
//    clock.)
//  - THE STEAMER'S NEAR SIDE lies STEAMER_OFF = 30 m from the shore line the route flies (her bay is cut as deep
//    as that asks): so that the whole boat is passed as a boat and not as a wall; the one steamer, moored for
//    the whole visit.
//  - THE SHOALS lie SHOAL.off = 18 m river-side of the route's shore line: low banks of sand near the route;
//    every shoal, from the avenue to the reed islet.
//  - THE REED ISLET lies ISLET.off = 14 m river-side of the shore line: so that its reeds are seen as reeds; the
//    one islet, where the shoals' row ends before the bend. ITS WADERS stand at its rim on the side of the line
//    and at its two ends (each bird's angle about the islet is dealt from the half round on the line's side and
//    half a radian more at either end).
//  - THE BANK'S POINT beyond the steamer's bay is thrown out until its reeds' outer edge comes within POINT_NEAR
//    = 11 m (to 12.5: the reach is a draw in that range; a metre more or less by the bank's own wander) of the
//    shore line's run, the cove beside it lying back COVE = 17 m: so the point and the leaning palms on it are
//    passed abeam before the bend; every point the land has room for.
//  - THE SHORE LOOP COMES AS NEAR THE LINE AS ITS RULES LET IT: its near side SHOAL_CLEAR beyond the furthest a
//    shoal's rim reaches, 30.6 m from the route's shore line as the shoals' measures stand, and never nearer
//    than ROUTE_CLEAR = 25 m: so that its sails are nearer the line; the whole loop (its three boats sail it on
//    the world's clock).
//  - THE SHORE EGRETS' COURSE lies midway between the flown line's clear air (AIR_CLEAR = 4 m river-side of the
//    line, read from the line itself beside the course) and the shore boats' reach (2 m bank-side of a boom's
//    end, 3.2 m beyond the shore loop's near side), from 10 m up-river of the sandbank to 10 m short of the reed
//    islet: over the open water between the way and the sails. (The flock flies it on the world's clock, and
//    only where it has its room; the course's place reads no clock.)
//  - THE LIONS' WAY IS LEFT OPEN: no palm of the bank's groves stands within 20 m of the avenue's axis along the
//    bank (none before the buried gate), no station of leaning palms within 17 m of it, and no station of tall
//    reed beds within 9 m of it (the bank's small reed clumps stand there as along the rest of the bank); a
//    station there draws its numbers and stands empty.
//  - THE ROW lies ROW_OUT = two turn radii (60 m) out from the cut's plane: from there the two middle kings are
//    seen whole; the whole row, from the bend to the quarter turn.
//  - NO PALM STANDS BETWEEN A KING AND AN EYE ON THE ROUTE: of the palms beside the front none stands from a
//    crown's reach (CROWN = 5 m) up-river of the last king's outer foot to FRONT_CLEAR down-river of the door:
//    where the sight from far down the shore line to the first king's outer foot crosses the bank, and a crown's
//    reach more; every station of that bank.
//  - THE WAY TO THE DOOR IS LEFT OPEN: the parapet is open for it (the part's WAY_HALF: half as broad again as
//    the way between the middle kings' pedestals), no small figure stands on the side of a middle king that
//    looks into the way (the part), and no fallen slab and no standing or walking bird is laid on the bank's
//    sand within that half breadth and 3 m of the door's axis.
//  - THE BLOWN SAND'S VEILS off the bluff's top stand far along from the kings: VEIL_FAR = 110 m, and twice
//    that, up-river of the last king; the other veils rise off the dunes' crests inland of the shore.
//  - THE HILL BEHIND THE BLUFF begins its climb 20 m behind the face's line (4 to 12 m in 80 m, rounded): so that
//    it stays out of sight from under the kings (and adds no shade); where the ground behind the face stands
//    over 30 m, the climb taken off toward the nose (whole to 20 m short of it, gone 40 m beyond it).
//  - THE DOOR'S RING (in the part) stands DOOR_IN = two thirds of the passage inside the face: so deep that the
//    jambs hide it from any eye more than some thirty degrees off the door's axis.
//  - THE PACE'S SLOWEST STRETCH begins at the quarter turn's middle metre (mHalf: a place found on the laid line
//    in the cliff's frame) and ends where the door's axis is met: the reason given for that place (the order of
//    p1m1) is that the four kings stand whole before the eye from there. The pace is a table of places in metres.
//  - THE TWO LOOKS' WINDOWS (the film's gaze) are places of the route found in the world's frame. At the buried
//    gate: from the last boulders' line passed, beyond which no boulder stands between the eye and the gate,
//    until the gate is abeam. At the second king's face: from the bend's first metre until the door's axis is
//    met, where the door lies dead ahead.
//  - THE MOON stands MOON.up = 23 degrees up and MOON.west = 13 degrees west of the up-river way (-Z), for the
//    whole visit: its bearing is told by where it stands in the picture along the way (a hand to the right of
//    the heading through the cataract and along the shore, out of the picture in the bend, left of the door's
//    axis on the straight in).
//  - THE FAR PLANES' SEAM (where each ring of ridges begins and ends) lies at the bearing straight down-river of
//    the door: behind every look of the flight; all three planes.
//  - THE CAMELS' TWO STRINGS keep half a round apart on the one course along the far crest (down its top, back
//    up its inland flank, behind the crest and out of the river's sight): so while one string is behind the
//    crest the other walks its top. (They walk on the world's clock from a start a stream deals; the course
//    and the half round read neither.)
//  - THE IBIS' TWO LINES lie IBIS_APART = 14 m apart: near enough to read as one flight out and back (a choice,
//    p1's); the two long lines; the ends are wider.
//  - THE STORKS OF THE RARE VISITS turn in one tall column over the river before the kings, about a typed place
//    of the cliff's frame (CW(70, 150), 112 m over the water): a standing sight from the first metre to the
//    last. (Whether a visit is a rare one is the visit's own draw; the column's place reads nothing.)
//  - AND ONE TYPED FOR THE WAY, NOT FOR A SIGHT: THE KINGS STAND FRONTS = 2 lengths of the cut front beyond the
//    steamer's bow (the first king's outer foot: KINGS_ALONG): the lead's order for the journey's proportion
//    (two in round six; five before it, when the far greater part of the journey was spent coming to the kings).
// NOT PLACINGS, BUT MADE BY HOW NEAR THE WAY LIES OR BY WHERE IT LOOKS (typed; the same on every seed; no lens
// read), said here beside the list:
//  - FINER NEAR THE WAY: the ground's mesh by its distance from the route's line (focus: fine near the route
//    and in sight, coarse under water and behind the cliff); a palm of the fuller kinds within 50 m of the
//    route, of the plain kinds beyond; a boulder of the fine mass where its skin lies within 30 m of the
//    channel's line and it stands over 3.4 m high, of the plain mass within 80 m, of the coarse beyond.
//  - THE RIVER'S MIDDLE SKY COLOUR is read from the sky at one typed bearing, thirty degrees up and up-river:
//    where the flight looks.
//  - WHAT NO PLACE BEFORE THE FRONT COULD SEE IS NOT DRAWN (in the part: unseen, BACK): a triangle of a carving
//    that lies inside other stone, or looks back into the cliff more steeply than any place before the front
//    could see; the same for every eye.
// THE LIST AS OF p1m6. HOW IT WAS CHECKED: at p1m5 the whole-line comments of this file and of the part were
// read once more for a placing whose words give a reason of sight from the way (seen, sight, in the picture,
// from the route, from the line, near the route, behind, before, in front of, hides, passed, abeam, looks), and
// the lines of code that call posAtDist, routeDist, lineDist or laneDist were looked at; at p1m6 the outside
// reader's finds were added (the channel's walls, the two courses, the pool and the clear axis, FRONTS) and the
// lines of code that read the line's own places (path.entry, path.heading, path.zBend, path.rowD, the flown
// line, the lane's end, the film's places) were looked at. LEFT OFF IT, by kind: the margins that only keep a
// body clear of the line and give no reason of sight (among them the dragonflies' clear air, the reeds' six
// metres, the swallows' height, the ibis' keep from the route's hook, the kings' loop's keep from the door's
// axis) and what is laid from the place alone (among them the sun's bearing, the village, the sandbank): these
// are said where they are made. A placing of this kind found later belongs here.
import * as THREE from 'three';
import { makePath, clamp, lerp, smoothstep } from '../kit/core.js';
import { makeSky } from '../kit/sky.js';
import * as T from '../kit/terrain.js';
import * as flora from '../kit/flora.js';
import * as F from '../kit/fauna.js';
import * as fx from '../kit/fx.js';
import { buildHero, figureGeometry, lionSolids, pieces, bedSteps, MEASURES } from '../parts/four-stone-kings-over-the-river.js';

const DUR = 40;
// the cataract: the boulders' field is FIELD metres of river, from its first line (B_Z0) up to its last (B_Z1); the
// avenue's axis AVENUE metres beyond the last boulders (a sandbank with its birds lies between); the steamer's berth
// (its middle along the bank, half its length, the gap from the avenue's up-river row to its stern, half its beam
// over the paddle boxes; its near side lies STEAMER_OFF metres from the shore line the route flies: the lead's
// order of round six, 26 to 34 m, so that the whole boat is passed as a boat and not as a wall)
const FIELD = 150, B_Z1 = -400, B_Z0 = B_Z1 + FIELD, AVENUE = 75, AV_Z = B_Z1 - AVENUE, AV_ROW = 6, STEAMER_OFF = 30;
const BERTH = { half: 16, gap: 30, beam: 3.25 };
BERTH.off = STEAMER_OFF + BERTH.beam;
BERTH.z = AV_Z - AV_ROW - BERTH.gap - BERTH.half;
// the shore: the west bank's line and how far off it the route's shore line runs
const SHORE_X = 88, SHORE_OFF = 18;
// the far bank opposite the bluff: its water's edge lies FAR_D out from the cut's plane, wandering FAR_WANDER either way.
// the long crest far inland of the near shore (CREST): its line lies so far inland of the shore's, it is so broad and
// so high; it rises over the hundred metres down-river of the boulder field's first line and falls over the last
// hundred before the bluff's hill (written where the ground is)
const FAR_D = 275, FAR_WANDER = 8, CREST = { x: SHORE_X + 252, w: 46, h: 26, rise: [10, -90], fall: [20, 120] };
// the kings: the steamer lies FRONTS lengths of the cut front down the bank from them (along the bank from them,
// never at their feet): the first king's outer foot stands that far beyond the steamer's bow. FRONTS is the lead's
// order for the journey's proportion (two in round six; five before it: the far greater part of the journey was
// then spent coming to the kings). F is the middle of the
// door's threshold; FOOT1 is where that foot lies in the cliff frame (s, d: the hero's own measure, handed out by
// the part), so F's z follows from the bow's place by that one rule, and the route's length falls where it falls
const FRONTS = 2, KINGS_ALONG = FRONTS * MEASURES.front, FOOT1 = MEASURES.foot, TT = [0.8, 0.6], TN = [-0.6, 0.8];
const FX = 60, FY = 1.6;
const FZ = BERTH.z - BERTH.half - Math.sqrt(KINGS_ALONG ** 2 - (SHORE_X - SHORE_OFF + BERTH.off - FX - FOOT1[0] * TT[0] - FOOT1[1] * TN[0]) ** 2) - FOOT1[0] * TT[1] - FOOT1[1] * TN[1];
// cliff frame to world and back
const CW = (s, d, y = 0) => [FX + s * TT[0] + d * TN[0], y, FZ + s * TT[1] + d * TN[1]];
const SD = (x, z) => [(x - FX) * TT[0] + (z - FZ) * TT[1], (x - FX) * TN[0] + (z - FZ) * TN[1]];
const lin = (hex) => new THREE.Color(hex);
const V3 = (a) => new THREE.Vector3(a[0], a[1], a[2]);

// ---------------------------------------------------------------- the one hour: the first sun, in three tempers
// Every visit is the first sun. This reach of the river runs toward the sunrise: the sun has just cleared the far
// bank down-river. It stands on the river side of the front, SUN_OUR degrees of bearing down-river of the front's
// own normal (OUR side is the down-river side), one bearing for every temper. Two faces of stone BOUND that
// bearing; they do not set it. The front's planes take the sun at the cosine of the bearing and the kings'
// down-river flanks at its sine, and what stands out from the wall throws its shade up-river along it by the
// tangent. The buried gate's river face looks square across the world's x, 53.1 degrees up-river of the front's
// normal: it has the sun only while the bearing is under 36.9 degrees, and further round it would lie in its own
// shade. That is the upper end, and the stone gives no lower one but nought. Inside that band 26 is the builder's
// choice, a typed number: at 26 the front takes the sun at 0.90 and the kings' down-river flanks at 0.44, a shade
// runs 0.49 of how far its thing stands out, and the gate's river face takes the sun raking, at 0.19 (the sine of
// 10.9 degrees). So every plane of the kings that looks down the river is in full warm sun; the niches, the door's
// reveal, the wall behind the kings and their up-river flanks are in clear violet shade; and so low a sun lays
// every king's shadow long along the front, up-river of him.
// A temper holds from the first metre to the last: el is the sun's height in degrees (6.5 to 10: plainly early in
// all three); ONE light for everything that stands here, written as radiance per unit albedo: sun (a face square
// to it: rose-gold), sky (what an upward face has from above), gnd (what a face has from below and from the side:
// the shade's own blue-violet). By these values a plane of the front in the sun carries five to six times the
// light of an upright plane in shade beside it (the sun at the cosine above, and half the sky and half the gnd on
// both; red, green and blue weighed as the eye weighs them: 5.5 in rose, 5.9 in gold, 5.6 in haze). The scene's
// two lamps (for sand, palms, birds) are made from the same three by sceneLight().
// fog is the haze's density (the air is clear: the front at 400 m keeps nine tenths of the contrast it has at 100 m
// in the thickest of the three; distance is told by the far planes of the land, not by haze),
// door the gate's glow on the threshold, mist how much mist lies on the far bank, river how strongly the rippled
// water throws the low sun back up at the stone that looks down on it, cloud how much of the sky the dawn's clouds
// take (least and most, by the visit's mood), moon how bright the pale moon is (where it stands is told at MOON).
const SUN_OUR = 26;
const TEMPERS = {
  // rose dawn: the sun 6.5 degrees up; a rose band low all round the sky under a deep blue, clouds lit pink from below
  rose: {
    el: 6.5, fog: 0.0007, door: 0.9, mist: 1, river: 0.16, cloud: [0.2, 0.3], moon: 0.75,
    sky: { preset: 'day', zenith: '#143684', mid: '#4f70be', horizon: '#dd9488', horizonPow: 3.3, scatterColor: '#ff9a78', scatter: 0.65, scatterPow: 3, scatterHigh: 0.1, sunColor: '#ffc8a8', sunSize: 1.6, sunIntensity: 9 },
    clouds: { lit: '#ffae9a', shade: '#7f72ac' },
    stone: { sun: [1.34, 0.66, 0.31], sky: [0.13, 0.18, 0.52], gnd: [0.1, 0.085, 0.42], rim: [0.06, 0.04, 0.05] },
  },
  // clear gold morning: the sun 8.5 degrees up; a gold band, clouds lit gold; the air clearest
  gold: {
    el: 8.5, fog: 0.0006, door: 0.9, mist: 0.5, river: 0.15, cloud: [0.16, 0.26], moon: 0.9,
    sky: { preset: 'day', zenith: '#133c8e', mid: '#5c86ca', horizon: '#e0b07a', horizonPow: 2.8, scatterColor: '#ffc270', scatter: 0.65, scatterPow: 3.6, sunColor: '#ffe6c0', sunSize: 1.5, sunIntensity: 12 },
    clouds: { lit: '#ffcf94', shade: '#8f84b2' },
    stone: { sun: [1.34, 0.8, 0.33], sky: [0.13, 0.19, 0.52], gnd: [0.1, 0.09, 0.42], rim: [0.06, 0.04, 0.05] },
  },
  // pale gold under high cloud: the sun 10 degrees up; an apricot band, more of the sky in cloud
  haze: {
    el: 10, fog: 0.0008, door: 0.9, mist: 0.8, river: 0.15, cloud: [0.3, 0.38], moon: 0.5,
    sky: { preset: 'day', zenith: '#1a3f8c', mid: '#5e7cbc', horizon: '#d2a688', horizonPow: 3.2, scatterColor: '#ffd4a0', scatter: 0.6, scatterPow: 2.6, scatterHigh: 0.2, sunColor: '#fff0d8', sunSize: 1.7, sunIntensity: 7 },
    clouds: { lit: '#ffd8b4', shade: '#9a90b8' },
    stone: { sun: [1.26, 0.78, 0.38], sky: [0.14, 0.2, 0.52], gnd: [0.105, 0.095, 0.42], rim: [0.06, 0.05, 0.06] },
  },
};
// the scene's lamps from a temper's light: a lamp of intensity I and colour c gives a matt face I c / pi per unit albedo
function sceneLight(stone) {
  const lamp = (a, k) => new THREE.Color(a[0] / k, a[1] / k, a[2] / k), sunK = Math.max(...stone.sun), skyK = Math.max(...stone.sky, ...stone.gnd);
  return { sun: lamp(stone.sun, sunK), sunI: Math.PI * sunK, sky: lamp(stone.sky, skyK), gnd: lamp(stone.gnd, skyK), hemiI: Math.PI * skyK };
}

// a smooth curve through keys [metres, value], flat beyond both ends
function keyed(keys) {
  return (m) => {
    if (m <= keys[0][0]) return keys[0][1];
    for (let i = 1; i < keys.length; i++) if (m <= keys[i][0]) return lerp(keys[i - 1][1], keys[i][1], smoothstep(keys[i - 1][0], keys[i][0], m));
    return keys[keys.length - 1][1];
  };
}

// ---------------------------------------------------------------- the route, by the stations of the place
// The line is laid from the place alone; boulders, palms, reeds and boats are laid round it.
// THE CATARACT: the entry stands in a pool of open water ENTRY_IN metres inside the boulders' field, chan.off metres
// river-side of the shore line (the seed's own channel: where its boulders leave the way open). From the pool the
// channel runs STRAIGHT metres straight at the door of the kings, level, 2.2 m over the water (so the front is seen
// up the channel from the first metre); then ONE ease carries the line over onto the shore line, which it joins
// JOIN metres beyond the last boulders.
// THE SHORE: SHORE_OFF metres off the bank's line, 2.6 to 4.2 m up, past the sandbank, the avenue's nearest lions
// and the steamer in its bay; the shore line runs straight on at the first king's feet, at a slant to the row.
// THE STRAIGHT IN: ITS LAW OF HEIGHT is laid first, from the kings: from IN_LOW metres over the water, IN_HEIGHTS
// of a king's own height out from the plane of their toes on the door's axis, an even climb to the door's middle
// at the threshold; then level down the passage to the portal, which stands GATE_IN metres inside the face (the
// part's own door anchor: two thirds down the passage). THE LINE FLIES ONLY THE INNER R_IN METRES OF THAT CLIMB:
// the quarter turn meets the axis R_IN out from the cut, and the land's edge lies 32 to 35 m out there, crossed in
// the turn's last metres: so the turn ends over the bank and the straight in flies no water, only the bank's sand
// and ledge and the terrace, between the middle pair. The two middle kings are seen whole, crown to footstool,
// from the row and from the turn, not from the straight's first metres.
// THE COMING IN: where the shore line has come within reach, one left bend of R_BEND brings the line parallel to
// the row, out on the river, ROW_OUT metres from the cut's plane; along the row to where the door's axis lies
// R_IN metres on; there ONE quarter turn to the right of R_IN onto the door's axis, which it meets ROW_OUT less
// R_IN metres out, at the height the straight in has there.
// (THE POLISH ROUND'S ONE CHANGE OF THE LINE: the row line ran R_IN beyond the straight's first metre, 91 m out
// from the cut; it runs ROW_OUT = 60 m out. With it the bend's first metre lies 39 m further up the shore line, the
// quarter turn (the same turn of R_IN) meets the axis 30 m out instead of 61, and the straight in is the same
// line at the same heights from there on: its law of height is unchanged, a climb from IN_LOW two kings'
// heights out to the door's middle at the threshold, of which the line now flies the inner 30 m.)
