// ---------------------------------------------------------------- granite boulders
// One weathered mass of granite as a ball of 20 * (detail + 1)^2 triangles: a block with all its edges long since
// rounded off, swollen and hollowed in broad lumps, with what granite has in its shape: two split faces (flat, with
// a crisp arris), a shell come off along a wavy line (a ledge), and joints as grooves. The joints are the three
// families of planes JOINTS in the ball's own frame; the shader draws the same planes as fine cracks. Every boulder
