const JOINTS = [[0.62, 0.35, 0.7, -0.22], [0.62, 0.35, 0.7, 0.34], [-0.55, 0.25, 0.8, 0.08], [0.12, 0.95, -0.28, -0.3], [0.12, 0.95, -0.28, 0.42]];
