    const POINTS = [];
    for (let z = bayEnd - rPoints.range(14, 24); z > cornerZ + 20; z -= rPoints.range(POINT_GAP[0], POINT_GAP[1])) POINTS.push([z, rPoints.range(COVE - POINT_NEAR - 1.5, COVE - POINT_NEAR), rPoints.range(11, 15)]);
    const onCoves = (z) => smoothstep(bayEnd + 6, bayEnd - 10, z) * smoothstep(cornerZ, cornerZ + 16, z);
    const pointAt = (z) => { let r = 0; for (const [zp, reach, half] of POINTS) { const dz = Math.abs(z - zp); if (dz < half) r = Math.max(r, reach * smoothstep(half, half * 0.3, dz)); } return r; };
    // (the bank's own wander is a metre on the coves' stretch and three or four elsewhere)
    const westX = (z) => { const cv = onCoves(z); return SHORE_X + (3 * noise.n2(z * 0.011, 3.3) + 1 * noise.n2(z * 0.045, 8.1)) * smoothstep(8, 26, Math.abs(z - AV_Z)) * (1 - 0.75 * cv) + 9 * smoothstep(B_Z1 + 20, B_Z0, z) + bayAt(z) + cv * (COVE + REED_OUT - SHORE_OFF - pointAt(z)); };
    const WEST_LEAST = SHORE_X - 5 - (COVE - POINT_NEAR - (COVE + REED_OUT - SHORE_OFF));
    // (the far bank's line: EAST_X beside the cataract; up-river of the last boulders it stands back EAST_BACK metres, over the avenue's own length of river)
    const EAST_BACK = 32, eastX = (z) => EAST_X - EAST_BACK * (1 - smoothstep(B_Z1 - AVENUE + 5, B_Z1, z)) + 3 * noise.n2(z * 0.009, 5.7);
    // the drift of sand that pours down the gully: one ridge whose crest runs down the gully's own axis (wavering a
    // metre or two) from the gully's head out onto the strand, where it runs out in a point. The crest stands
    // GULLY.mouth metres high at the mouth, climbs inside the gully at DRIFT.climb and falls beyond the mouth to
    // nothing in DRIFT.run metres; its lee side (up-river: the wind comes from down-river) lies at the angle sand
