        // brow, under the part's own shoulder; behind the door it stands back to leave the passage open
        const sf = scarpFar(s), b0 = lerp(9 + 5 * smoothstep(13, 7, Math.abs(s)), PLATEAU[0], sf), top = bluffTop(s) - 5;
        if (sf > 0) hc += apronAt(s, back) * smoothstep(0, 6, mc);
