    for (let k = -1; k <= 1; k++) reedClump(rIslet, islet[0], islet[1] + k * islet[2] * 0.5, Math.round(rIslet.range(3, 6) * density));
    // the reed beds of the west bank's shallows (a stream of their own): every 7 to 12 m a bed that reaches from the
