        const xx = x0 - rBed.range(-0.5, 4.5), zz = z + rBed.range(-3, 3), sc = rBed.range(0.9, 1.3), rot = rBed.range(0, Math.PI * 2), v = rBed.int(0, 1), l = open ? land(xx, zz) : 9;
        if (l > -REED_OUT && l < 0.8) reedPts.push({ x: xx, y: Math.max(ground(xx, zz), level - 0.6), z: zz, s: sc * (l < -1.4 ? 1.5 : 1), rot, v, u: 0, d: 0, deep: l < -1.4 });
