      await pause(1.2);
      const lionBox = [-1.4, 0, -2.6, 1.4, 3.1, 2.7], lionGeo = await figureGeometry(lionSolids(rLion), lionBox, 0.21, pause);
      {
        // old worn stone, darker with desert varnish than the towers; sand in the hollows of the back and about the foot
        const bk = lionGeo.attributes.aBake, nr = lionGeo.attributes.normal, ps = lionGeo.attributes.position, mk = lionGeo.attributes.aMark;
        for (let v = 0; v < bk.count; v++) { bk.setX(v, bk.getX(v) * 0.82); bk.setZ(v, Math.max(0.45 * smoothstep(0.7, 0.97, nr.getY(v)), 0.6 * smoothstep(0.9, 0.3, ps.getY(v)))); mk.setX(v, 0.8); }
      }
      await pause(3);
      const M = new THREE.Matrix4(), Q = new THREE.Quaternion(), E = new THREE.Euler(), S3 = new THREE.Vector3(), P3 = new THREE.Vector3(), casters = [];
      const lions = new THREE.InstancedMesh(lionGeo, stone, 8);
      // the two rows stand AV_ROW metres to either side of the avenue's axis, the first lion of each a metre inside
