          const ss = sb + rSlab.range(-2.5, 2.5), inl = rSlab.range(1.5, BANK_OUT - 1.5), size = rSlab.range(SLAB.small[0], SLAB.small[1]);
          if (Math.abs(ss) < HA.way.half + 3) { for (let k = 0; k < 6; k++) rSlab(); continue; }
