        uSunDir: { value: SUN.clone() }, uSunCol: { value: C3(H.stone.sun) }, uSky: { value: C3(H.stone.sky) }, uGnd: { value: C3(H.stone.gnd) }, uShade: { value: shade }, uThrough: { value: through },
