      for (const sg of [-1, 1]) sl.quad([-13.5, 3.72, sg * 2.6], [12, 3.72, sg * 2.6], [12, 4.6, sg * 2.6], [-13.5, 4.6, sg * 2.6], white, [0, 4, 0]);
      sl.quad([-13.5, 3.72, -2.6], [-13.5, 3.72, 2.6], [-13.5, 4.6, 2.6], [-13.5, 4.6, -2.6], white, [0, 4, 0]);
      // the upper house, the wheelhouse forward of it, the funnel between, a pole mast with nothing flying from it
      sl.block(-6, 2.2, -1.5, 1.5, 3.72, 5.7, 0, 0, white, white, [0.7, 0.68, 0.62]);
      for (let x = -5.3; x < 1.6; x += 1.7) for (const sg of [-1, 1]) sl.quad([x, 4.5, sg * 1.53], [x + 0.8, 4.5, sg * 1.53], [x + 0.8, 5.3, sg * 1.53], [x, 5.3, sg * 1.53], dark, [0, 5, 0]);
      sl.block(5.4, 8.4, -1.4, 1.4, 3.72, 6.0, 0, 0, white, white, [0.7, 0.68, 0.62]);
      for (const sg of [-1, 1]) sl.quad([5.7, 4.95, sg * 1.43], [8.1, 4.95, sg * 1.43], [8.1, 5.6, sg * 1.43], [5.7, 5.6, sg * 1.43], dark, [7, 5, 0]);
